ASSIGN=json.loads(Path('.cache/batch200/rewrite_st.json').read_text())
HAIR=[['希腊 hairein 拿取、选择；haireisthai 为自己选择','不是拉丁 haerere 黏附，也不是表示继承人的 heres']]
HERET=HAIR+[['希腊 hairetikos 能选择的、属于某学派的 → 教会拉丁 haereticus','在教会语境中转为异端的、持异端者']]
GASTR=[['希腊 gaster，属格 gastros','胃、肚腹；构词中常见 gastr-、gastro-']]
ZEL=[['希腊 zelos 热切、竞相追求，也可指嫉妒 → 拉丁 zelus','同一份强烈在意，可以往投入，也可以往占有和竞争发展']]
ZELOUS=ZEL+[['中世纪拉丁 zelosus → 英语 zealous','经较直接的拉丁借入线，主要保留热心、热切义']]
JEAL=ZEL+[['晚期拉丁 zelosus → 古法语 jalos／gelos → 英语 jealous','经法语路线，现代常指嫉妒或唯恐失去']]
ZEALOT=[['希腊 zelos 热切、竞相追求 → zelotes 热切追随者','从热切的态度形成持这种态度的人的称谓'],['晚期拉丁 zelotes → 英语 zealot','早期宗教称谓，后来泛指狂热追随某事业或信念的人']]
W=[
E('symposium','英 /sɪmˈpəʊziəm/；美 /sɪmˈpoʊziəm/','专题研讨会；专题讨论文集；古希腊饮酒会','一群人围绕同一个主题交流意见，今天通常是有组织的学术或专业活动。','借拉丁 symposium，来自希腊 symposion 饮酒聚会；sym- 是 syn- 一起的同化形式，后半接表示喝的 po- 词干。pin- 与 po- 是希腊相关词形，不是英语随意换字母。',[['希腊 syn- 一起 + 与 posis 饮酒相关的词干 → symposion','原来是聚在一起饮酒交谈的场合'],['拉丁 symposium → 英语 symposium','经古典作品与聚会用法，发展为围绕主题的讨论会']],'古希腊的饮酒会常伴交谈，后来名称转到专题讨论。现代会议不要求喝酒；复数 symposia、symposiums 都可见，也能指围绕一题汇集的文章。','hold a symposium；a symposium on climate change；an international symposium。','conference 范围更广，可能含很多议题；symposium 常集中一个主题。seminar 常是较小范围的讲授讨论，workshop 更强调实际参与和练习。',('The university hosted a symposium on urban housing.','大学举办了一场关于城市住房的专题研讨会。'),('Her essay appears in a symposium on the future of museums.','她的文章收录在一组关于博物馆未来的专题讨论文章中。'),sources=['https://www.etymonline.com/word/symposium','https://www.oxfordlearnersdictionaries.com/definition/english/symposium','https://www.merriam-webster.com/dictionary/symposium']),
E('heresy','/ˈherəsi/','异端；被视为违背正统的见解','某个群体认为一套信念越出了它认可的边界；也能半开玩笑说一种想法冒犯了行业里的常识。','希腊 hairesis 原是选择、学派，经拉丁 haeresis 与古法语 heresie 进入英语。意思从选择一种学说，转到被某种正统视为错误的学说。',HAIR+[['希腊 hairesis 选择、学派 → 拉丁 haeresis','教会语境逐渐出现偏离正统之义'],['古法语 heresie → 中古英语 heresie → heresy','异端；后来也比喻挑战公认观点的意见']],'be accused of heresy 是被指控持异端；在技术团队里说 This is heresy 可能只是幽默地表示这想法太不合常规。它是相对某种正统的判断，不是词本身已经证明观点真假。','be accused of heresy；religious heresy；commit heresy。','heresy 是见解或持这种见解的行为，heretic 是人。atheism 是不信有神，和在宗教内部持不同教义不是一回事。',('The council condemned the teaching as heresy.','会议把那套教导斥为异端。'),('Suggesting fewer meetings sounded like heresy to the management team.','提议减少会议，在管理团队听来简直是离经叛道。'),sources=['https://www.etymonline.com/word/heresy','https://www.oxfordlearnersdictionaries.com/definition/english/heresy']),
E('heretic','/ˈherətɪk/','持异端者；挑战正统见解的人','大家都认可一套说法，这个人却坚持另一套，因此被别人看作越界者。','经古法语 eretique 接教会拉丁 haereticus、希腊 hairetikos。历史形容词能作人物名称，不是英语 heresy 去尾字母后临时加 -tic。',HERET+[['古法语 eretique → 中古英语 heretyk → heretic','持有被视为异端的观点的人']],'a religious heretic 是宗教语境；an economic heretic 可以指不接受主流经济理论的人。后者可能是批评，也可能赞赏敢于挑战成见。','brand someone a heretic；a religious heretic；an intellectual heretic。','dissenter 泛指不同意的人；heretic 特别涉及挑战一套被当成正统的原则。heretic 也不必是毫无信仰的人。',('The authorities branded him a heretic for questioning the doctrine.','当局因他质疑那项教义而把他定为异端。'),('Within the profession, she was regarded as a daring heretic.','在业内，她被视为一个大胆挑战正统的人。'),sources=['https://www.etymonline.com/word/heretic','https://www.oxfordlearnersdictionaries.com/definition/english/heretic']),
E('heretical','/həˈretɪkəl/','异端的；违背正统的；离经叛道的','用来形容那套不被正统接受的观点、教导或做法。','现代可辨 heretic + -al；历史经法语 eretical 或直接接中世纪拉丁 haereticalis，来自 haereticus。这里保留独立借入路线。',HERET+[['中世纪拉丁 haereticalis → 法语 eretical／英语 heretical','属于异端的；后来也用于挑战通行观念的主张']],'heretical beliefs 是异端信念；a heretical idea 在非宗教文章中常是与主流很不一致的想法。重音从 heretic 的开头移到第二音节。','heretical beliefs；a heretical idea；be considered heretical。','unusual 只是不同寻常；heretical 暗示触碰了被群体视为原则的东西。historical 历史的与它拼写、来源都不同。',('The book was banned because its arguments were considered heretical.','那本书因论点被视为异端而遭禁。'),('At the time, the proposal sounded almost heretical to traditional designers.','当时，这项提议在传统设计师听来几乎是离经叛道。'),sources=['https://www.etymonline.com/word/heretical','https://www.oxfordlearnersdictionaries.com/definition/english/heretical']),
E('diaeresis','/daɪˈerəsɪs/','分音符；分音','两个相邻元音容易被当成一组发音，符号提醒你把它们分开，例如 naïve 中 i 上的两点。','经拉丁 diaeresis 接希腊 diairesis 分开，来自 diairein 拆开：dia- 分开 + hairein 拿取。不要拆成否定的 die 或英语 erase。',HAIR+[['希腊 dia- 分开 + hairein → diairein → diairesis','把组合拆开，尤其将元音分开发音'],['拉丁 diaeresis → 英语 diaeresis','分音现象；以及标示它的两点符号']],'英式常写 diaeresis，美式也常写 dieresis；复数 diaereses。英语排印里常见于 naïve、coöperate 等形式，有些写法会省略这个符号。','a diaeresis over a vowel；the diaeresis in naïve；use a diaeresis。','umlaut 外形也常是两点，但在德语等语言中主要表示元音改变；diaeresis 说明相邻元音分开读，功能不同。',('The diaeresis in naïve shows that the vowels belong to separate syllables.','naïve 中的分音符表明那两个元音属于不同音节。'),('This publisher retains the diaeresis in words such as coöperate.','这家出版社在 coöperate 这样的词中保留分音符。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/diaeresis','https://en.wiktionary.org/wiki/diaeresis#English']),
E('gastric','/ˈɡæstrɪk/','胃的；与胃有关的','告诉你所谈的位置是胃，例如胃酸、胃液或胃壁。','借新拉丁 gastricus，来自希腊 gaster、gastr-；现代可识别 gastr- 胃 + -ic 相关的。',GASTR+[['新拉丁 gastricus → 英语 gastric','与胃有关的医学形容词']],'gastric acid 是胃酸；gastric juice 是胃液。它主要指胃这个器官，不是把整个腹部都叫 gastric。','gastric acid；gastric juice；the gastric lining。','gastric 侧重胃；gastrointestinal 包括胃与肠；abdominal 指腹部，范围更广。gastric 与 gas 气体并非同一个词根。',('The diagram shows the glands that produce gastric acid.','示意图展示了产生胃酸的腺体。'),('The researchers examined changes in the gastric lining.','研究人员检查了胃黏膜的变化。'),sources=['https://www.etymonline.com/word/gastric','https://www.oxfordlearnersdictionaries.com/definition/english/gastric']),
E('gastrointestinal','英 /ˌɡæstrəʊɪnˈtestɪnəl/；美 /ˌɡæstroʊɪnˈtestɪnəl/','胃肠的；胃肠道的','把胃和肠连成一条消化食物的通路来谈，常缩写为 GI。','gastro- 胃 + intestinal 肠的，是近代医学用希腊与拉丁来源成分组合的词；并非一个完整的古希腊单词直接借入。',GASTR+[['近代 gastro- + intestinal → gastrointestinal','胃与肠相关；常见缩写 GI']],'gastrointestinal symptoms 是胃肠道症状；gastrointestinal tract 指食物通过的消化道。字面重点是胃肠，但术语 GI tract 的实际范围可涵盖整条消化道。','the gastrointestinal tract；gastrointestinal symptoms；GI disorders。','gastric 只指胃；intestinal 只指肠；gastrointestinal 合在一起说。digestive system 还包括协助消化的肝、胰等器官，不只是食物通过的管道。',('The chapter describes the structure of the gastrointestinal tract.','这一章介绍胃肠道的结构。'),('Participants recorded any gastrointestinal symptoms in a diary.','参与者把出现的胃肠道症状记录在日记中。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/gastrointestinal','https://en.wiktionary.org/wiki/gastrointestinal#English','https://www.niddk.nih.gov/health-information/digestive-diseases/digestive-system-how-it-works']),
E('gastroenteritis','英 /ˌɡæstrəʊˌentəˈraɪtɪs/；美 /ˌɡæstroʊˌentəˈraɪtɪs/','胃肠炎','常与腹泻、呕吐等相连的一类胃肠道炎症或感染性疾病名称。','gastro- 胃 + enter- 肠 + -itis 炎症；近代医学按古典成分组成。字面能帮助识别，但不能据此断言每个病例都同时累及胃和肠。',GASTR+[['希腊来源 gastro- + enter- + -itis → 医学 gastroenteritis','胃肠道炎症名称；具体感染部位随病因而异']],'viral gastroenteritis 是病毒性胃肠炎，主要是肠道感染。俗称 stomach flu，但并不是流感病毒感染胃；词义也不能代替对具体病因的判断。','viral gastroenteritis；an outbreak of gastroenteritis；acute gastroenteritis。','gastritis 是胃炎；gastroenteritis 名称包含肠。influenza 是流感，与俗称 stomach flu 所指的胃肠炎不同。',('The school reported several cases of gastroenteritis.','学校报告了几例胃肠炎。'),('The leaflet explains why viral gastroenteritis is not influenza.','宣传单解释了为什么病毒性胃肠炎不是流感。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/gastroenteritis','https://medlineplus.gov/gastroenteritis.html','https://www.niddk.nih.gov/health-information/digestive-diseases/viral-gastroenteritis/definition-facts']),
E('gastroenterology','英 /ˌɡæstrəʊˌentəˈrɒlədʒi/；美 /ˌɡæstroʊˌentəˈrɑːlədʒi/','胃肠病学；消化内科学','医院里研究和处理消化系统问题的专科名称，不只是研究食物好不好吃。','gastro- 胃 + entero- 肠 + -logy 学科；属于近代国际医学构词。字面点出胃肠，现实专科也涉及食管、肝、胰等消化相关器官。',GASTR+[['近代 gastro- + entero- + -logy → gastroenterology','研究消化系统功能和疾病的医学领域']],'a gastroenterology department 是消化科；specialise in gastroenterology 是从事这一专科。拆成长串时，先抓胃、肠、学科三个块就容易看懂。','the gastroenterology department；specialise in gastroenterology；a gastroenterology clinic。','gastronomy 是美食、烹饪和饮食文化；gastroenterology 是医学。字面都有胃，却不是同一种学问。',('She works in the hospital’s gastroenterology department.','她在医院消化科工作。'),('The conference brought together researchers in gastroenterology.','会议汇集了消化医学领域的研究人员。'),sources=['https://www.merriam-webster.com/dictionary/gastroenterology','https://www.oxfordlearnersdictionaries.com/definition/english/gastroenterology','https://gi.org/wp-content/uploads/2011/10/WhatIsAGastroenterologist.pdf']),
E('gastroenterologist','英 /ˌɡæstrəʊˌentəˈrɒlədʒɪst/；美 /ˌɡæstroʊˌentəˈrɑːlədʒɪst/','胃肠专科医生；消化内科医生','把上一个学科名换成人：专门处理消化系统问题的医生。','对应 gastroenterology 的 -logist 人员形式；不是在完整 -logy 后面再机械加 -ist 而保留 y。',GASTR+[['近代 gastro- + entero- + -logy → gastroenterology','消化系统医学领域'],['对应的 -logist 专家名称 → gastroenterologist','从事这一专科的医生']],'see a gastroenterologist 是看消化科医生。读医院介绍时也会见到 GI doctor 这个较短的说法；范围不只限胃疼，也涉及其他消化系统问题。','consult a gastroenterologist；a consultant gastroenterologist；a paediatric gastroenterologist。','nutritionist 主要谈营养，gastroenterologist 是医学专科医生。gastronome 是讲究美食的人，不能拿来称这类医生。',('The gastroenterologist reviewed the test results with him.','消化科医生和他一起查看了检查结果。'),('A gastroenterologist contributed the chapter on digestive disorders.','消化系统疾病那一章由一位消化科医生撰写。'),sources=['https://www.merriam-webster.com/dictionary/gastroenterology','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/gastroenterologist','https://gi.org/wp-content/uploads/2011/10/WhatIsAGastroenterologist.pdf']),
E('gastropod','英 /ˈɡæstrəpɒd/；美 /ˈɡæstrəpɑːd/','腹足类动物','蜗牛、蛞蝓这类动物属于这一大类，常靠腹面宽大的肌肉足移动。','希腊 gastr- 腹 + pod- 足，组成近代分类名 Gastropoda，英语也与法语 gastéropode 相连。腹足说的是身体下方的足，不是胃自己变成脚。',GASTR+[['希腊 gastr- 腹 + pod- 足 → 新拉丁分类名 Gastropoda／法语 gastéropode','按腹面肌肉足命名'],['英语 gastropod','这一动物类别的成员，也可作关系形容词']],'a land gastropod 是陆生腹足类；许多有壳，但蛞蝓等没有明显外壳。不能把是否背着螺壳当成唯一判断标准。','a marine gastropod；a land gastropod；gastropod shells。','mollusc 软体动物是更大的类群；gastropod 是其中一支。snail 蜗牛是常见成员，gastropod 不只等于蜗牛。',('A slug is a gastropod even though it has no obvious external shell.','蛞蝓虽然没有明显的外壳，仍是腹足类动物。'),('The collection contains gastropod shells from the coast.','藏品中有一些来自海岸的腹足类贝壳。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/gastropod','https://en.wiktionary.org/wiki/gastropod#English']),
E('zeal','/ziːl/','热忱；热情；干劲','认定一件值得做的事，就带着强烈的动力去追求。','经古法语 zel 或直接接晚期拉丁 zelus，远接希腊 zelos。它与 jealous 同源，但这条名词线通常保留热切投入的意思。',ZEL+[['古法语 zel／拉丁 zelus → 英语 zeal','对目标、事业或信仰的热切投入']],'zeal for reform 是改革热情；with renewed zeal 是重新鼓起干劲。它偏正式，常肯定投入，也可以在语境里暗示热情过头。','zeal for reform；religious zeal；with renewed zeal。','enthusiasm 很常用；zeal 常带认真追求某项目标的强烈劲头。zealot 却通常已经带狂热、偏执的批评意味。',('She approached the restoration project with remarkable zeal.','她怀着非凡的热忱投入修复项目。'),('His zeal for reform impressed the younger staff.','他的改革热情打动了年轻员工。'),sources=['https://www.etymonline.com/word/zeal','https://www.oxfordlearnersdictionaries.com/definition/english/zeal']),
E('zealous','/ˈzeləs/','热心的；热切投入的','做事非常上心，愿意投入大量精力，有时也显得过分认真。','来自中世纪拉丁 zelosus；现代可以联想 zeal + -ous，但历史并非只在英语里临时派生。它与经法语来的 jealous 是同源双词。',ZELOUS,'a zealous supporter 是热心支持者，zealous efforts 是十分投入的努力。注意读 /ˈzeləs/，不是把 zeal 的 /iː/ 原样保留下来。','a zealous supporter；a zealous campaigner；zealous efforts。','zealous 通常说热心投入；jealous 常说嫉妒或怕失去。overzealous 才直接说明过了头。',('A zealous volunteer reorganised the entire archive.','一位十分热心的志愿者重新整理了整个档案库。'),('She remained a zealous defender of the library.','她一直热切地捍卫这家图书馆。'),sources=['https://www.etymonline.com/word/zealous','https://www.oxfordlearnersdictionaries.com/definition/english/zealous']),
E('zealously','/ˈzeləsli/','热切地；积极投入地','强调动作带着很强的投入感，例如积极推动、认真捍卫。','zealous + -ly；保持 /ˈzeləs/ 的读音再接 /li/。',ZELOUS+[['英语 zealous + -ly → zealously','以热心、热切投入的方式']],'work zealously 是热心工作；defend something zealously 是积极捍卫。语气是否赞赏，要看投入的目标和是否过分。','work zealously；campaign zealously；defend something zealously。','jealously guard 常突出不愿失去或让人分享；zealously defend 突出投入、卖力。两个副词近形同源，现代重心不同。',('The team worked zealously to reopen the theatre.','团队满腔热情地努力，让剧院重新开放。'),('He zealously defended the proposal at every meeting.','他在每次会上都积极为提案辩护。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/zealously','https://www.etymonline.com/word/zealous']),
E('overzealous','英 /ˌəʊvəˈzeləs/；美 /ˌoʊvərˈzeləs/','过分热心的；积极过头的','本想认真把事办好，却因为太卖力、太严格而做过了头。','over- 过度 + zealous 热心的；英语用前缀直接标出程度超过合适范围。',ZELOUS+[['英语 over- + zealous → overzealous','热心或积极到了过度的程度']],'an overzealous official 可能执法、审查太严；overzealous editing 可能把作者本来需要的细节也删掉。它常承认有积极动机，却批评结果失当。','an overzealous official；overzealous enforcement；overzealous editing。','enthusiastic 可以纯粹褒义；overzealous 明确认为过度。careless 是不够用心，几乎是另一个方向的问题。',('An overzealous editor removed every informal phrase.','一位过分较真的编辑删掉了所有非正式表达。'),('The organiser apologised for the overzealous security checks.','组织者为过度严格的安检道歉。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/overzealous','https://en.wiktionary.org/wiki/overzealous#English']),
E('zealot','/ˈzelət/','狂热分子；狂热追随者','坚持某种信念到了很难听进其他意见的程度，通常是批评性的称呼。','经晚期拉丁 zelotes 来自希腊 zelotes 热切追随者。英语早期与宗教历史称谓相连，后来泛指狂热支持某种事业的人；不是英语 zeal 随意加 -ot。',ZEALOT,'a political zealot 是政治狂热者；a religious zealot 是宗教狂热者。历史上的 Zealot 常大写，涉及古代特定称谓；普通小写用法范围更广。','a religious zealot；a political zealot；an ideological zealot。','enthusiast 可以只是爱好者，zealot 通常暗示僵硬、排斥异议。对一个人说有 zeal 不等于称他为 zealot。',('The novel portrays him as a zealot who cannot tolerate disagreement.','小说把他塑造成无法容忍异议的狂热者。'),('She was a committed reformer, but no zealot.','她是坚定的改革者，却不是狂热分子。'),sources=['https://www.etymonline.com/word/zealot','https://www.oxfordlearnersdictionaries.com/definition/english/zealot']),
E('zealotry','/ˈzelətri/','狂热；狂热偏执的行为','谈的不是某一个狂热者，而是一种把信念推到不容异议的态度和做法。','zealot + -ry，英语形成表示态度、行为的名词；它不只等于 zeal 的较长写法。',ZEALOT+[['英语 zealot + -ry → zealotry','狂热追随者的态度或行为']],'religious zealotry、political zealotry 都常带贬义；通常不可数。可以批评一种处理问题的方式，无需指认某个组织名称。','religious zealotry；political zealotry；ideological zealotry。','zeal 是强烈热情，未必不好；zealotry 通常已经暗示偏执和不宽容。determination 则是坚定，不必排斥不同意见。',('The book warns against replacing evidence with ideological zealotry.','书中告诫不要用意识形态狂热取代证据。'),('His enthusiasm gradually hardened into zealotry.','他的热情逐渐变成了僵硬的狂热。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/zealotry','https://www.merriam-webster.com/dictionary/zealotry','https://en.wiktionary.org/wiki/zealotry#English']),
E('jealous','/ˈdʒeləs/','嫉妒的；吃醋的；唯恐失去的','别人拥有你想要的东西，或你担心自己珍视的关系被人抢走，心里因此不舒服。','晚期拉丁 zelosus 经古法语 jalos、gelos 进入英语。zealous 后来走较直接的拉丁路线；两者同源，却不是现代英语互相改拼得到。',JEAL,'jealous of her success 是嫉妒她的成功；a jealous partner 常指伴侣关系里的吃醋。口语 I’m jealous! 也可以轻松表示羡慕，语气不一定恶意。','be jealous of；feel jealous；a jealous partner；jealous of one’s independence。','传统辨析把 envy 偏向想要别人拥有的，jealousy 偏向怕失去自己的；现代 jealous 也广泛用于前一种场景，不能把它判成一律错误。',('He was jealous of his colleague’s rapid promotion.','他嫉妒同事升职那么快。'),('She felt jealous when her partner kept praising someone else.','伴侣不停称赞另一个人时，她有些吃醋。'),sources=['https://www.etymonline.com/word/zeal','https://www.oxfordlearnersdictionaries.com/definition/english/jealous']),
E('jealousy','/ˈdʒeləsi/','嫉妒；醋意；猜忌','把想要别人拥有的、或怕失去自己珍视之物的那种情绪作为名词来谈。','来自古法语 jalousie，接 jalos 嫉妒的，远接拉丁 zelosus。英语名词有独立法语借入线，不是只把 jealous 后面加一个 y。',ZEL+[['拉丁 zelosus → 古法语 jalos → jalousie → 英语 jealousy','热切关注、占有与嫉妒的情绪名称']],'a pang of jealousy 是突然一阵嫉妒；professional jealousy 是同行间因比较而生的妒意。通常不可数，复数 jealousies 可指多方之间的不同猜忌和妒意。','a pang of jealousy；professional jealousy；out of jealousy。','jealousy 是情绪，jealous 是形容词。envy 常强调想拥有别人已有的东西，两者在日常用法有重叠。',('She felt a brief pang of jealousy when she heard the news.','听到消息时，她短暂地生出一阵嫉妒。'),('Professional jealousy damaged their working relationship.','同行间的嫉妒损害了他们的工作关系。'),sources=['https://www.etymonline.com/word/jealousy','https://www.oxfordlearnersdictionaries.com/definition/english/jealousy']),
E('jealously','/ˈdʒeləsli/','嫉妒地；吃醋地；严密守护地','可以描述带着嫉妒看别人，也可以说紧紧护住属于自己的东西，不愿让它被夺走或泄露。','jealous + -ly；沿着嫉妒、唯恐失去这两种相关意思使用。',JEAL+[['英语 jealous + -ly → jealously','嫉妒地；不愿失去地保护着']],'watch jealously 是怀着妒意看；a jealously guarded secret 是严格保守的秘密。后一种常不带爱情嫉妒，而是在强调珍惜、维护占有。','look jealously at；jealously guard a secret；jealously protect independence。','zealously 强调积极投入；jealously protect 常强调不让已有的权利、独立或秘密失去。jealously guarded 不宜直译成嫉妒地守卫。',('He watched jealously as his brother opened the new bicycle box.','弟弟打开新自行车箱子时，他嫉妒地看着。'),('The family has jealously guarded the recipe for generations.','这个家族世代严守这份配方。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/jealously','https://www.etymonline.com/word/jealousy']),
]
